mapper.select:
select
    DATE_FORMAT(so.create_time, '%Y-%m') as month,
    COALESCE(
        sum(
so.order_money
        ), 0
    ) as amount
from sal_sed_order as so
where so.is_deleted = 0
and so.customer_id = #{customerId}

    and so.create_time >= #{startTime}


    and so.create_time <= #{endTime}

group by DATE_FORMAT(so.create_time, '%Y-%m')
order by month
